[hidden] { display: none !important; }

/* 2026-09-06 review */
.lm-intro { color: var(--text-secondary); margin-bottom: 1rem; }
.lm-icon-primary { color: var(--primary-color); }
.lm-icon-muted { color: var(--border-color); }
